//! Class ids and their names, from UnityPy's MIT `enums/ClassIDType.py`
//! (368 ids in 1.25.2). Names are for people and output naming; the core
//! works in `i32` and never needs a name to read a file. UnityPy extends its
//! enum at runtime for an unknown id; [`class_name`] returns `None` for one.
//!
//! Owner: package A. `CLASS_NAMES` is generated by `tools/gen/gen_tables.py`
//! from the oracle's UnityPy 1.25.2 (plan section 2.6); the scaffold ships it
//! empty. The constants below are the ids the core itself uses and stay.

/// `AssetBundle`: read at load for the container (`SerializedFile.py:316-324`).
pub const ASSET_BUNDLE: i32 = 142;
/// `MonoBehaviour`: the script-tree provider hook (`ObjectReader.py:298-304`).
pub const MONO_BEHAVIOUR: i32 = 114;
/// `MonoScript`: what a `MonoBehaviour`'s `m_Script` points at.
pub const MONO_SCRIPT: i32 = 115;

/// `(id, name)` pairs sorted by id.
// STUB(A): empty until tools/gen/gen_tables.py generates it (plan 2.6).
pub static CLASS_NAMES: &[(i32, &str)] = &[];

/// UnityPy's `ClassIDType` name for `id`.
#[must_use]
pub fn class_name(id: i32) -> Option<&'static str> {
    let i = CLASS_NAMES.binary_search_by_key(&id, |(k, _)| *k).ok()?;
    CLASS_NAMES.get(i).map(|(_, n)| *n)
}
